1.STL 的 stack 操作(常用方法)：push(i) //入栈(该函数用于在堆栈顶部插入新元素。)pop(i)  //弹栈(该函数用于删除元素，堆栈中的元素从顶部删除。)empty()  //检查栈是否为空 s.empty() ? true 为空: falsetop()   //查看栈顶元素    size()  //查看栈中数组的大小

样例代码:#include &lt;iostream&gt;  // 包含输入输出流库，用于控制台输出操作#include &lt;stack&gt;     // 包含C++标准库中的栈容器，提供栈的基本操作（入栈、出栈、取栈顶等）// 定义dome函数，用于演示标准库栈的基本用法void dome() &#123;    stack&lt;int&gt; s;  // 声明一个存储int类型元素的栈对象s    // 循环将1到10共10个整数依次压入栈中    for (int i = 1; i &lt;= 10; i++) &#123;        s.push(i);  // push()：栈的入栈操作，将元素i添加到栈顶    &#125;    // 打印当前栈中元素的数量    // size()：返回栈中元素的个数    printf(&quot;num:%d\n&quot;, s.size());    // 循环弹出并打印栈中所有元素，直到栈为空    // empty()：判断栈是否为空，返回true表示空栈，false表示非空    while (!s.empty()) &#123;        cout &lt;&lt; s.top() &lt;&lt; &quot; &quot;;  // top()：获取栈顶元素（不弹出），并通过cout输出        s.pop();                 // pop()：弹出栈顶元素（删除栈顶元素，无返回值）    &#125;&#125;// 主函数，程序入口int main() &#123;    dome();  // 调用dome函数，执行栈的演示操作    return 0;  // 程序正常结束&#125;

2.数组模拟 的 stack 操作(常用方法)：1.对数组进行操作模拟栈操作://// Created by PINGJU on 2025/11/4.//// 栈类的头文件：基于动态数组实现的静态容量栈（最大容量由N指定）// 提供入栈、出栈、取栈顶、判断空栈、获取元素个数等核心操作//#ifndef UNTITLED_STACKARR_H#define UNTITLED_STACKARR_H#include &lt;stdexcept&gt;  // 包含异常处理相关头文件，用于抛出栈操作异常（如空栈、满栈）const int N = 100010;  // 栈的最大静态容量，可根据需求调整（固定大小，不支持动态扩容）// 基于动态数组的栈类（StackArr = Stack + Array）class StackArr &#123;public:    StackArr();         // 构造函数：初始化栈的内存和栈顶指针    ~StackArr();        // 析构函数：释放栈占用的动态内存，避免内存泄漏    // 模拟栈的基本操作    void push(int x);   // 入栈操作：将元素x添加到栈顶    int pop();          // 出栈操作：移除并返回栈顶元素    bool isEmpty();     // 判断栈是否为空：空返回true，非空返回false    int top();          // 获取栈顶元素：仅返回不删除    int size();         // 获取当前栈中元素的个数private:    int *arr;  // 动态分配的数组，用于存储栈的元素    int tt;    // 栈顶指针：-1 表示空栈，0~N-1 表示栈顶元素的索引（元素个数 = tt + 1）&#125;;#endif //UNTITLED_STACKARR_H  // 头文件保护宏结束，防止重复包含

//// Created by PINGJU on 2025/11/4.//// 栈类的实现文件：对应 StackArr.h 中声明的成员函数的具体实现//#include &quot;StackArr.h&quot;  // 包含栈类的头文件，关联声明与实现using namespace std;   // 引入标准命名空间，简化异常抛出等语法// 构造函数：初始化栈的状态StackArr::StackArr() : tt(-1) &#123;  // 初始化列表：将栈顶指针tt设为-1（表示初始为空栈）    this-&gt;arr = new int[N];  // 动态分配大小为N的int数组，作为栈的存储容器&#125;// 析构函数：释放动态内存StackArr::~StackArr() &#123;    delete[] arr;  // 释放arr指向的动态数组（注意用delete[]匹配数组的new）&#125;// 入栈操作：将元素x压入栈顶void StackArr::push(int x) &#123;    // 检查栈是否已满（tt+1 等于N时，数组索引已达上限，无法再存元素）    if (tt + 1 &gt;= N) &#123;        throw runtime_error(&quot;Stack is full!&quot;);  // 栈满时抛出运行时异常，提示错误    &#125;    this-&gt;arr[++this-&gt;tt] = x;  // 栈顶指针先上移（++tt），再将x存入当前栈顶位置&#125;// 出栈操作：移除栈顶元素并返回其值int StackArr::pop() &#123;    // 检查栈是否为空，空栈无法执行出栈操作    if (isEmpty()) &#123;        throw runtime_error(&quot;Pop from empty stack!&quot;);  // 空栈时抛出运行时异常    &#125;    return this-&gt;arr[tt--];（先返回栈顶元素，再下移指针）&#125;// 判断栈是否为空bool StackArr::isEmpty() &#123;    return tt == -1;  // 栈顶指针为-1时，栈中无元素，返回true&#125;// 获取栈顶元素（不删除）int StackArr::top() &#123;    // 检查栈是否为空，空栈无栈顶元素可获取    if (isEmpty()) &#123;        throw std::runtime_error(&quot;Get top from empty stack!&quot;);  // 空栈时抛出异常    &#125;    return this-&gt;arr[this-&gt;tt];  // 返回栈顶指针tt指向的元素（当前栈顶）&#125;// 获取当前栈中元素的个数int StackArr::size() &#123;    return tt + 1;  // 元素个数 = 栈顶指针索引 + 1（tt从-1开始，空栈时0个元素）&#125;
